const PROPERTY_ID = env.get('PROPERTY_ID') || 'demo-hotel';
const VACANT_MINUTES = parseInt(env.get('VACANT_MINUTES') || '2', 10);

const topic = msg.topic || '';
const parts = topic.split('/');
// smartroom / property / zone / device / kind
const zoneId = parts[2];
const device = parts[3];
const kind = parts[4];

if (!zoneId || !device || !kind) return null;

// Estado global de zonas en contexto.
let zones = context.global.get('zones') || {};
if (!zones[zoneId]) {
  zones[zoneId] = { zone_id: zoneId, devices_online: {}, pending_cmd_ids: [], updated_at: new Date().toISOString() };
}
const z = zones[zoneId];

if (kind === 'state') {
  const state = msg.payload;
  if (device === 'lighting') {
    z.lighting_scene = state.lighting_scene;
    z.dimmer_level = state.dimmer_level;
  } else if (device === 'climate') {
    z.thermostat_temp = state.thermostat_temp;
    z.thermostat_setpoint = state.thermostat_setpoint;
    z.hvac_mode = state.hvac_mode;
  } else if (device === 'curtains') {
    z.curtains_position = state.curtains_position;
  } else if (device === 'occupancy') {
    z.occupancy_status = state.occupancy_status;
    // Regla R1/R2: vacancia y llegada
    handleVacancyRules(zoneId, state.occupancy_status);
  }
  z.last_cmd_id = state.last_cmd_id || null;
  z.updated_at = state.ts || new Date().toISOString();
}

if (kind === 'status') {
  z.devices_online = z.devices_online || {};
  z.devices_online[device] = (msg.payload === 'online');
}

z.updated_at = new Date().toISOString();
context.global.set('zones', zones);

// Emitir zona actualizada por WebSocket.
const wsNodes = context.global.get('wsNodes') || [];
wsNodes.forEach((ws) => {
  try { ws.send(JSON.stringify({ type: 'zone_update', zone: z })); } catch (e) {}
});

return { payload: z, topic: `api/zones/${zoneId}` };

function handleVacancyRules(zoneId, occupied) {
  const now = Date.now();
  const vacantKey = `vacant_${zoneId}`;
  const vacantStart = context.global.get(vacantKey);

  if (occupied) {
    // R2: llegada y estaba en eco -> welcome
    if (z.lighting_scene === 'eco') {
      publishCmd(zoneId, 'lighting', { type: 'set_scene', value: 'welcome' });
      emitEvent(zoneId, 'automation', 'Regla R2 llegada: escena welcome');
    }
    context.global.set(vacantKey, null);
    return;
  }

  // No ocupada: iniciar/contar vacancia
  if (!vacantStart) {
    context.global.set(vacantKey, now);
    return;
  }
  const minutesIdle = (now - vacantStart) / 60000;
  if (minutesIdle >= VACANT_MINUTES && z.lighting_scene !== 'eco') {
    // R1: vacancia >= umbral -> eco
    publishCmd(zoneId, 'lighting', { type: 'set_scene', value: 'eco' });
    publishCmd(zoneId, 'curtains', { type: 'set_curtains', value: 0 });
    publishCmd(zoneId, 'climate', { type: 'set_setpoint', value: 25.0 });
    emitEvent(zoneId, 'automation', 'Regla R1 vacancia: escena eco');
  }
}

function publishCmd(zoneId, device, cmd) {
  cmd.cmd_id = cmd.cmd_id || require('crypto').randomUUID();
  cmd.origin = 'automation';
  cmd.ts = new Date().toISOString();
  node.send({ topic: `smartroom/${PROPERTY_ID}/${zoneId}/${device}/cmd`, payload: cmd });
  if (!z.pending_cmd_ids) z.pending_cmd_ids = [];
  z.pending_cmd_ids.push(cmd.cmd_id);
}

function emitEvent(zoneId, type, message) {
  const event = { id: require('crypto').randomUUID(), ts: new Date().toISOString(), zone_id: zoneId, type, message };
  let events = context.global.get('events') || [];
  events.unshift(event);
  if (events.length > 100) events.length = 100;
  context.global.set('events', events);
  const wsNodes = context.global.get('wsNodes') || [];
  wsNodes.forEach((ws) => {
    try { ws.send(JSON.stringify({ type: 'event', event })); } catch (e) {}
  });
}

const zones = context.global.get('zones') || {};
const mqttConnected = context.global.get('mqttConnected') || false;
const startTime = context.global.get('startTime') || Date.now();
return {
  payload: {
    status: 'ok',
    mqtt: mqttConnected ? 'connected' : 'disconnected',
    zones: Object.keys(zones).length,
    uptime_s: Math.floor((Date.now() - startTime) / 1000),
  },
};

const { zone_id } = req.params;
const { type, value } = req.body || {};
const demoKey = req.headers['x-demo-key'];
const expectedKey = env.get('DEMO_KEY');

if (!demoKey || demoKey !== expectedKey) {
  return { statusCode: 401, payload: { error: { code: 'unauthorized', message: 'clave de demo inválida' } } };
}

const zones = context.global.get('zones') || {};
if (!zones[zone_id]) {
  return { statusCode: 404, payload: { error: { code: 'not_found', message: 'zona no existe' } } };
}

const validTypes = ['set_scene','set_dimmer','set_setpoint','set_hvac_mode','set_curtains','sim_occupancy'];
if (!type || !validTypes.includes(type)) {
  return { statusCode: 400, payload: { error: { code: 'invalid_type', message: 'tipo de comando inválido' } } };
}

// Validaciones de rango
if (type === 'set_dimmer' && (!Number.isInteger(value) || value < 0 || value > 100)) {
  return { statusCode: 400, payload: { error: { code: 'invalid_value', message: 'dimmer 0-100' } } };
}
if (type === 'set_curtains' && (!Number.isInteger(value) || value < 0 || value > 100)) {
  return { statusCode: 400, payload: { error: { code: 'invalid_value', message: 'cortinas 0-100' } } };
}
if (type === 'set_setpoint' && (typeof value !== 'number' || value < 16 || value > 30)) {
  return { statusCode: 400, payload: { error: { code: 'invalid_value', message: 'setpoint 16-30' } } };
}
if (type === 'set_hvac_mode' && !['auto','cool','heat','off'].includes(value)) {
  return { statusCode: 400, payload: { error: { code: 'invalid_value', message: 'hvac_mode auto|cool|heat|off' } } };
}
if (type === 'set_scene') {
  const scenes = ['welcome','relax_sunset','work','cinema','night','eco'];
  if (!scenes.includes(value)) {
    return { statusCode: 400, payload: { error: { code: 'invalid_value', message: 'escena inexistente' } } };
  }
}

const cmd_id = require('crypto').randomUUID();
const cmd = { cmd_id, type, value, origin: 'dashboard', ts: new Date().toISOString() };

node.send({ payload: cmd, topic: `smartroom/${env.get('PROPERTY_ID') || 'demo-hotel'}/${zone_id}/lighting/cmd` });
node.send({ payload: cmd, topic: `smartroom/${env.get('PROPERTY_ID') || 'demo-hotel'}/${zone_id}/climate/cmd` });
node.send({ payload: cmd, topic: `smartroom/${env.get('PROPERTY_ID') || 'demo-hotel'}/${zone_id}/curtains/cmd` });

// Guardar comando pendiente
let zones = context.global.get('zones') || {};
if (zones[zone_id]) {
  zones[zone_id].pending_cmd_ids = zones[zone_id].pending_cmd_ids || [];
  zones[zone_id].pending_cmd_ids.push(cmd_id);
  context.global.set('zones', zones);
}

return { payload: { cmd_id }, statusCode: 202 };

const events = context.global.get('events') || [];
const limit = Math.min(parseInt(req.query.limit || '50', 10), 100);
return { payload: events.slice(0, limit) };

try {
  const msg = JSON.parse(msg.payload);
  if (msg.type === 'ping') {
    return { payload: JSON.stringify({ type: 'hello', server_time: new Date().toISOString() }) };
  }
} catch (e) {}
return null;
